import{_ as n,C as a,o as r,c as s,j as t,a as i,E as c,a6 as d}from"./chunks/framework.CCKCzdWs.js";const h="/screenshots/picker-popup.png",b=JSON.parse('{"title":"Browser extension","description":"Piwi Picker, the browser extension: pick and lint locators, record actions and copy context for an agent on the live page, with or without a Piwi instance.","frontmatter":{"title":"Browser extension","description":"Piwi Picker, the browser extension: pick and lint locators, record actions and copy context for an agent on the live page, with or without a Piwi instance.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/extension.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/extension.html"}],["meta",{"property":"og:title","content":"Browser extension | Piwi Dashboard"}],["meta",{"property":"og:description","content":"Piwi Picker, the browser extension: pick and lint locators, record actions and copy context for an agent on the live page, with or without a Piwi instance."}]]},"headers":[],"relativePath":"features/extension.md","filePath":"features/extension.md","lastUpdated":1793082143000}'),l={name:"features/extension.md"};function p(g,e,u,f,m,w){const o=a("Needs");return r(),s("div",null,[e[0]||(e[0]=t("h1",{id:"browser-extension",tabindex:"-1"},[i("Browser extension "),t("a",{class:"header-anchor",href:"#browser-extension","aria-label":'Permalink to "Browser extension"'},"​")],-1)),c(o,{extension:""}),e[1]||(e[1]=d('<p>Piwi Picker is a Chrome, Edge and Firefox extension that picks ranked, stable Playwright locators from the page you are looking at, scored by the same engine the dashboard uses, and records a multi-page flow into a runnable TypeScript spec. It works standalone and sends nothing by default; connecting it to a Piwi instance adds what needs your project&#39;s history.</p><h2 id="what-it-does" tabindex="-1">What it does <a class="header-anchor" href="#what-it-does" aria-label="Permalink to &quot;What it does&quot;">​</a></h2><p>Every tool below runs on the live page, from the toolbar popup. The last three need a <a href="#connecting-to-a-piwi-instance">connection to a Piwi instance</a>; the others never reach it.</p><table tabindex="0"><thead><tr><th>Tool</th><th>For</th></tr></thead><tbody><tr><td><a href="./pick-an-element.html">Pick an element</a></td><td>a ranked locator for one element, re-checked against the page</td></tr><tr><td><a href="./pick-an-element.html#multi-pick">Multi-pick</a></td><td>the shared pattern of a list&#39;s rows or cards</td></tr><tr><td><a href="./lint-overlay.html">Lint overlay</a></td><td>the elements that would make bad locator targets</td></tr><tr><td><a href="./pick-an-element.html#assertion-suggester">Assertion suggester</a></td><td><code>expect(...)</code> lines for an element</td></tr><tr><td><a href="./pick-an-element.html#copy-context-for-agent">Copy context for agent</a></td><td>one block about an element for a coding agent</td></tr><tr><td><a href="./record-actions.html">Record actions</a></td><td>a runnable spec from clicks and fills across pages</td></tr><tr><td><a href="./report-a-bug.html">Report a bug</a></td><td>a failing test and a report of a bug you reproduce</td></tr><tr><td><a href="./devtools.html">Developer tools</a></td><td>in DevTools: the selected element&#39;s locators, the locator console, the session, mocks, viewports</td></tr><tr><td><a href="./record-actions.html#matching-functions">Matching functions</a></td><td>a recording that calls your own functions</td></tr><tr><td><a href="#test-functions-against-this-page">Test functions</a></td><td>which of your functions work on this page</td></tr><tr><td><a href="#tested-elements">Tested elements</a></td><td>which elements of this page your tests reach</td></tr></tbody></table><h2 id="where-it-is" tabindex="-1">Where it is <a class="header-anchor" href="#where-it-is" aria-label="Permalink to &quot;Where it is&quot;">​</a></h2><p>Install Piwi Picker from the <strong><a href="https://chromewebstore.google.com/detail/piwi-picker/pakhnokpjboejcghgcmkjlpnogfjihhe" target="_blank" rel="noreferrer">Chrome Web Store ↗</a></strong> for Chrome or Edge 118 or later (in Edge, click <strong>Allow</strong> on the <em>Allow extensions from other stores</em> banner once, then <strong>Get</strong>), or from <strong><a href="https://addons.mozilla.org/firefox/addon/piwi-picker/" target="_blank" rel="noreferrer">Firefox Add-ons ↗</a></strong> for Firefox 140 or later.</p><p>Every tool in the popup has a tile with a line under its name saying what it is for, and a key (<code>1</code> records, <code>2</code> picks, <code>B</code> reports a bug). One tool runs at a time and <strong>Esc</strong> cancels it; recording runs until its own <strong>Stop</strong>. The tools that need no pick on the page are in the browser&#39;s DevTools: <a href="./devtools.html">Developer tools</a>.</p><figure><img src="'+h+'" alt="The Piwi Picker popup over a shop page, one tile per tool"><figcaption>The popup: one tile per tool, with its key.</figcaption></figure><p>Picking also has a shortcut, <code>Ctrl+Shift+E</code> by default (<code>Cmd+Shift+E</code> on macOS); the popup footer shows the key bound.</p><h2 id="test-functions-against-this-page" tabindex="-1">Test functions against this page <a class="header-anchor" href="#test-functions-against-this-page" aria-label="Permalink to &quot;Test functions against this page&quot;">​</a></h2><p><strong>Test functions</strong> in the popup scores every function of the active project&#39;s catalog against the page: <strong>Ready to use here</strong> (every step finds one element), <strong>Partly found here</strong>, or <strong>Not on this page</strong>.</p><h2 id="tested-elements" tabindex="-1">Tested elements <a class="header-anchor" href="#tested-elements" aria-label="Permalink to &quot;Tested elements&quot;">​</a></h2><p>With a connection, <a href="./tested-elements.html">Tested elements</a> outlines every element of the page a test of the active project reaches, lists those tests, and marks the buttons, links and fields no test reaches.</p><h2 id="languages" tabindex="-1">Languages <a class="header-anchor" href="#languages" aria-label="Permalink to &quot;Languages&quot;">​</a></h2><p>Piwi Picker speaks English, French, German, Spanish and Brazilian Portuguese, following the browser unless <strong>Language</strong>, in the settings, picks another. German, Spanish and Portuguese are unreviewed drafts: <a href="https://github.com/PiwiTests/piwi/issues/new?template=translation.yml" target="_blank" rel="noreferrer">suggest a correction</a>. A bug report is written in the extension&#39;s language; locators, test ids and specs never are.</p><h2 id="permissions-explained" tabindex="-1">Permissions, explained <a class="header-anchor" href="#permissions-explained" aria-label="Permalink to &quot;Permissions, explained&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Permission</th><th>Why</th></tr></thead><tbody><tr><td><code>activeTab</code></td><td>acts on the tab you are looking at, only when you click the toolbar icon or press the shortcut</td></tr><tr><td><code>debugger</code> (Chrome and Edge)</td><td>trusted input for a <a href="./replay-a-bug-report.html">replay</a>, a bug report&#39;s console, requests and screenshots, and DevTools&#39; <a href="./mock-requests.html#slow-down-or-fail-a-request">throttling</a>, attached only while one of them runs, under Chrome&#39;s own debugging bar. Without it (Firefox, or <strong>Cancel</strong> there), they use the page&#39;s events. Nothing leaves your machine</td></tr><tr><td><code>scripting</code></td><td>injects the picker or the recorder into that tab on demand, and marks your instance&#39;s pages once <a href="./extension-connection.html#what-is-sent">connected</a>; nothing else runs unasked</td></tr><tr><td><code>storage</code></td><td>keeps your copy format and, only if you connect, the instance URL, URL patterns, cached catalogs and the last three <a href="./tested-elements.html">locator indexes</a>, on your machine. The API key and the desktop app&#39;s and editor&#39;s tokens live in the extension&#39;s own database, out of reach of web pages; the session and a running recording use <code>chrome.storage.session</code>, cleared when the browser closes</td></tr><tr><td><code>cookies</code> (optional, not granted in advance)</td><td><a href="./devtools.html#save-login-for-tests">Save login for tests</a> asks for it, for the one site whose login you save</td></tr><tr><td><code>optional_host_permissions</code> (none granted in advance)</td><td>recording asks for the one site you are on, to follow you across its pages; a connection asks for your instance&#39;s origin. Never <code>&lt;all_urls&gt;</code>. The settings list every site allowed under <strong>Sites Piwi Picker may run on</strong>, each with <strong>Revoke</strong></td></tr></tbody></table><h3 id="sites-piwi-picker-may-run-on" tabindex="-1">Sites Piwi Picker may run on <a class="header-anchor" href="#sites-piwi-picker-may-run-on" aria-label="Permalink to &quot;Sites Piwi Picker may run on&quot;">​</a></h3><p>Recording, replaying, Save login and the DevTools pane each ask for the site you are on the first time they need it, and the access stays until you take it back. Settings → <strong>Sites Piwi Picker may run on</strong> lists every site allowed with a <strong>Revoke</strong> button; Piwi Picker then runs there only when you click its icon. A site a recording or a replay runs on keeps its access until it ends, and your instance&#39;s address, the desktop app&#39;s and the editor&#39;s are given back by <strong>Disconnect</strong> and <strong>Unpair</strong>.</p><h2 id="connecting-to-a-piwi-instance" tabindex="-1">Connecting to a Piwi instance <a class="header-anchor" href="#connecting-to-a-piwi-instance" aria-label="Permalink to &quot;Connecting to a Piwi instance&quot;">​</a></h2><p>Optional and off by default. In the settings, type your instance&#39;s address and click <strong>Connect</strong>, then <strong>Allow</strong> in the tab that opens: Piwi Picker receives its own API key. Which project applies on a page comes from URL patterns kept on the instance and from any you keep in this browser; the popup&#39;s <strong>Active project</strong> select overrides both for the session. See <a href="./extension-connection.html">Extension connection</a>.</p><p>Function catalogs refresh in the background. <strong>A recording is never sent to your instance</strong>, and a <a href="./bug-reports.html">bug report</a> only from its preview.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>One frame at a time.</strong> The picker and the recorder see the top-level document, not iframes.</li><li><strong>Open shadow roots only.</strong> The picker reaches inside open shadow roots; a closed one is out of reach, and a pick there picks its host element. The recorder records the fields of open shadow roots, and from a closed one only the keys of a password field (Enter, Escape, the arrows).</li><li><strong>Recording covers one origin.</strong> On another site it stops capturing: stop and review, or start again there.</li><li><strong>No aria-snapshot copier</strong> yet for <code>toMatchAriaSnapshot()</code>.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/recipes/broken-locator.html">Fix a broken locator</a>: from a failing locator to the one to use instead</li><li><a href="./extension-connection.html">Extension connection</a>: connecting in one step, and the URL patterns kept on the instance</li><li><a href="./tested-elements.html">Tested elements</a>: the elements your tests reach, drawn on the page</li><li><a href="./test-functions.html">Test functions catalog</a>: the functions a recording can call</li><li><a href="./locator-healing.html">Locator healing</a>: the replacement Piwi proposes after a failure</li></ul>',26))])}const y=n(l,[["render",p]]);export{b as __pageData,y as default};
